   },
   {
    "code": "SAMPLE_SIZE_POWER",
    "text": "120 team-seasons (30 teams over 4 seasons) is a moderate sample size for establishing a reliable team trait. The reliability of a difference score (H2-H1) is generally lower than the reliability of the raw scores, potentially requiring more data than available to achieve useful statistical power, especially if the underlying effect is subtle."
   }
  ]
 },
 "prior_work": {
  "already_answered": "no",
  "cited": [],
  "summary": "No prior research questions or findings directly address a defense's effect on opponents' H2-H1 change as a reliable team trait. The concept of \"H2-H1 change\" is not defined in the project's glossary or present in research questions."
 },
 "risks": [
  {
   "code": "CONFOUNDING",
   "text": "The H2-H1 change in opponent performance can be influenced by many factors beyond the specific defense, such as game state (score margin, clock), opponent coaching adjustments, opponent fatigue, home/away advantage, and individual player performance variance. These confounding factors must be carefully controlled or accounted for."
  },
  {
   "code": "MEASURE_RELIABILITY",
   "text": "Difference scores (H2-H1) are often less reliable than the scores from which they are derived. Establishing the reliability of a defense's effect on such a metric will be challenging, requiring robust statistical methods."
  },
  {
   "code": "BASE_RATE",
   "text": "If the average H2-H1 change in opponent performance is close to zero, or highly variable across games, detecting a consistent and reliable defensive trait will be difficult."
  }
 ],
 "predicted_outcome": {
  "supported": 0.1,
  "rejected": 0.2,
  "untestable": 0.4,
  "artifact": 0.1,
  "uncertain": 0.2
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "The intraclass correlation coefficient (ICC) for a specific defense's effect on its opponents' H2-H1 offensive rating (ORtg) change, calculated across games within a season and across seasons. The effect is defined as the mean H2-H1 ORtg change of opponents when playing against a specific defense, adjusted for confounding factors.",
  "unit": "Team-season for the defensive team. Individual games will be the observations used to calculate the team-season average effect.",
  "sample": "120 team-seasons across the 2022-23, 2023-24, 2024-25, and 2025-26 NBA regular seasons. Data from the 2025-26 regular season will be included up to 2026-04-13. Playoff games will be excluded to maintain consistency of competition level.",
  "power": "A power analysis will be conducted post-hoc if the effect is not found, to estimate the minimum detectable effect size given the observed variance and sample size. Given the moderate sample size and the nature of difference scores, achieving high power for subtle effects may be challenging.",
  "controls": "Game-level controls will include opponent strength (e.g., opponent's season average offensive rating), game location (home/away), score differential at halftime, and opponent's game pace. Team-level controls (e.g., defensive team's overall defensive rating) will also be considered in a hierarchical model.",
  "falsification": "The hypothesis is falsified if the estimated intraclass correlation coefficient (ICC) for the defense's effect on opponent H2-H1 ORtg change is not statistically significantly greater than zero (p > 0.05), after accounting for within-team variance and controlling for confounding factors, suggesting no reliable trait.",
  "multiplicity": "No multiple testing correction is required as the primary estimand is a single ICC for a predefined metric. If multiple metrics for 'H2-H1 change' are explored (e.g., ORtg, points per possession), appropriate adjustments (e.g., Bonferroni correction or FDR) will be applied.",
  "decision_rule": "The hypothesis will be considered supported if the lower bound of the 95% confidence interval for the intraclass correlation coefficient (ICC) is above a pre-specified threshold (e.g., 0.3, indicating moderate reliability) and the p-value for the ICC being greater than zero is less than 0.05.",
  "data_version": "NBA 2022-23, 2023-24, 2024-25 complete regular season data. NBA 2025-26 regular season data complete up to 2026-04-13. Play-by-play data, box-score summary data from the NBA stats API, and derived play-type possession records will be used to calculate opponent offensive rating for each half."
 }
}

